import {chromium} from '@playwright/test';import assert from 'node:assert/strict';import fs from 'node:fs/promises';import {KEY,scenarioState,makeTask} from '../src/model.js';
const dir='检查记录/复盘回看_20261022',browser=await chromium.launch({executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe',headless:true,args:['--no-proxy-server']}),p=await browser.newPage(),results=[],errors=[];p.setDefaultTimeout(7000);p.on('pageerror',e=>errors.push(e.message));
async function load(scene='PT01',width=1440,lang='zh',route='/plan?tab=复盘'){await p.setViewportSize({width,height:width===1711?949:width<720?844:1000});await p.goto('http://127.0.0.1:5184/plan');await p.evaluate(({s,key,lang})=>{localStorage.setItem(key,JSON.stringify(s));localStorage.setItem('career-prototype-language',lang);localStorage.setItem('career-prototype-operation-guide-v1',JSON.stringify({enabled:false,neverPrompt:true}));},{s:typeof scene==='string'?scenarioState(scene):scene,key:KEY,lang});await p.goto('http://127.0.0.1:5184'+route);await p.locator('.action-review').waitFor();await p.addStyleTag({content:'*,*::before,*::after{animation:none!important;transition:none!important}'});}
const state=()=>p.evaluate(key=>JSON.parse(localStorage.getItem(key)),KEY);
async function shot(name,review,block=true){const el=p.locator('.action-review');await el.evaluate(e=>e.scrollIntoView({block:'start'}));await p.screenshot({path:dir+'/实际截图/'+name+'-视口.png'});if(review)await p.screenshot({path:'.impeccable/review/'+review+'.png'});if(!block)return;const v=p.viewportSize(),box=await el.boundingBox();await p.setViewportSize({width:v.width,height:Math.ceil(box.height+650)});const style=await p.addStyleTag({content:'.flow-progress{visibility:hidden!important}'});await el.screenshot({path:dir+'/实际截图/'+name+'-板块.png'});await style.evaluate(e=>e.remove());await p.setViewportSize(v);}
async function check(name,fn){try{await fn();results.push({name,status:'pass'});console.log('PASS',name);}catch(e){results.push({name,status:'fail',error:e.message});console.log('FAIL',name,e.message.slice(0,700));await p.screenshot({path:dir+'/失败-'+results.length+'.png'});}}
try{
await check('空态三种切入点可操作、演示明确虚构且不写入业务，空历史不占位',async()=>{await load();const before=await state();assert.equal(await p.locator('.review-journal-history').count(),0);assert.equal(await p.locator('.review-journal form').count(),0);for(const name of ['遇到的问题','外部反馈','有效做法']){await p.getByRole('button',{name,exact:true}).click();assert.equal(await p.getByRole('button',{name,exact:true}).getAttribute('aria-pressed'),'true');assert.match(await p.locator('.review-spark-demo').innerText(),/虚构演示/);}assert.match(await p.locator('.review-spark-demo').innerText(),/检查清单/);const after=await state();for(const key of ['tasks','reviews','claims','reviewDrafts','goal','budget','planVersion'])assert.deepEqual(after[key],before[key]);await shot('1440-复盘起点','desktop');await load('PT01',1711);await p.getByRole('button',{name:'外部反馈',exact:true}).click();await shot('1711-反馈切入点',null,false);});
await check('空态可以经原补录流程关联本人行动，再进入复盘而非假示例',async()=>{await load();await p.getByRole('button',{name:'添加实践记录',exact:true}).click();await p.getByLabel('行动标题',{exact:true}).fill('整理课程笔记（合成验收）');await p.getByLabel('本人实际行动和结果',{exact:true}).fill('我整理了笔记并留下两个疑问（合成验收）');await p.getByRole('button',{name:'保存真实类型自述（原型本地）',exact:true}).click();const s=await state();assert.equal(s.tasks.length,1);assert.equal(s.claims.length,1);assert.equal(s.claims[0].status,'待确认');assert.equal(s.reviews.length,0);assert.equal(await p.getByLabel('复盘任务',{exact:true}).inputValue(),s.tasks[0].id);assert.equal(await p.getByLabel('实际结果与贡献',{exact:true}).inputValue(),'');await p.locator('.review-source-record>summary').click();await p.getByRole('button',{name:'引用到结果草稿',exact:true}).click();assert.match(await p.getByLabel('实际结果与贡献',{exact:true}).inputValue(),/两个疑问/);});
await check('切入点和参考不覆盖本人草稿，下一做法即时回看并保持任务隔离',async()=>{const s=scenarioState('PT05');s.tasks.push({...makeTask(s,{title:'第二行动（合成）',hours:0}),id:'second'});await load(s);await p.getByLabel('实际结果与贡献',{exact:true}).fill('我整理了字段疑问（合成）');await p.getByRole('button',{name:'遇到的问题',exact:true}).click();assert.match(await p.locator('#review-current-prompt').innerText(),/遇到了什么问题/);await p.locator('.review-prompt-example>summary').click();assert.equal(await p.getByLabel('实际结果与贡献',{exact:true}).inputValue(),'我整理了字段疑问（合成）');await p.getByRole('button',{name:'填写改进措施',exact:true}).click();assert.equal(await p.getByLabel('改进措施',{exact:true}).evaluate(e=>document.activeElement===e),true);await p.getByLabel('改进措施',{exact:true}).fill('下次先核对字段，再动手（合成）');assert.match(await p.locator('.review-takeaway').innerText(),/下次先核对字段/);await shot('1440-本人下一做法');const id=(await state()).tasks[0].id;await p.getByLabel('复盘任务',{exact:true}).selectOption('second');assert.equal(await p.getByLabel('实际结果与贡献',{exact:true}).inputValue(),'');await p.getByLabel('复盘任务',{exact:true}).selectOption(id);await p.getByRole('button',{name:'填写改进措施',exact:true}).count();await p.getByRole('button',{name:'编辑改进措施',exact:true}).click();assert.equal(await p.getByLabel('改进措施',{exact:true}).inputValue(),'下次先核对字段，再动手（合成）');await p.reload();await p.locator('.review-step-tabs button').nth(2).click();assert.match(await p.getByLabel('改进措施',{exact:true}).inputValue(),/先核对字段/);});
await check('原必填和保存边界保留，回执/历史显出本人结果与下一做法，修订保留原版',async()=>{const s=scenarioState('PT05');await load(s);await p.getByRole('button',{name:'保存复盘',exact:true}).click();assert.equal(await p.getByLabel('实际结果与贡献',{exact:true}).evaluate(e=>document.activeElement===e),true);await p.getByLabel('实际结果与贡献',{exact:true}).fill('实际结果（合成）');await p.getByRole('button',{name:'保存复盘',exact:true}).click();await p.getByLabel('原因分析',{exact:true}).fill('输入说明不够，仍待核对（合成）');await p.locator('.review-step-tabs button').nth(2).click();await p.getByLabel('改进措施',{exact:true}).fill('先核对输入说明（合成）');await p.getByRole('button',{name:'保存复盘',exact:true}).click();const after=await state();assert.equal(after.reviews.length,1);for(const key of ['tasks','goal','budget','planVersion','claims','reports'])assert.deepEqual(after[key],s[key]);assert.match(await p.locator('.review-saved-receipt').innerText(),/实际结果（合成）/);assert.match(await p.locator('.review-history-entry>summary').innerText(),/先核对输入说明/);await shot('1440-保存回执');await p.locator('.review-history-entry>summary').click();await p.getByRole('button',{name:'修订复盘',exact:true}).click();assert.equal(await p.locator('dialog[open]').count(),1);await p.getByLabel('改进措施',{exact:true}).fill('先核对输入并记录疑问（合成）');const save=p.locator('dialog[open]').getByRole('button',{name:'保存复盘修订',exact:true});await save.click();const revised=(await state()).reviews[0];assert.equal(revised.version,2);assert.equal(revised.history[0].next,'先核对输入说明（合成）');});
await check('手机中宽英文及长标题可用，键盘切换与上下文焦点保留，失效引用不混草稿',async()=>{for(const [width,lang] of [[390,'zh'],[390,'en']]){await load('PT01',width,lang);assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);if(lang==='en')assert.equal((await p.locator('.action-review').innerText()).match(/[\u4e00-\u9fff]+/g),null);await shot(width+'-空态-'+lang,lang==='zh'?'mobile':null,lang==='zh');}for(const [width,lang] of [[390,'zh'],[1024,'zh'],[390,'en']]){const s=scenarioState('PT05');s.tasks[0].title=(lang==='en'?'Long personal action title (synthetic) ':'很长的本人行动标题（合成）').repeat(15);if(lang==='en'){s.tasks[0].purpose='Synthetic personal question';s.tasks[0].standard='Synthetic output';}await load(s,width,lang);const cue=p.locator('.review-cue-picker button').nth(2);await cue.focus();await cue.press('Enter');assert.equal(await cue.getAttribute('aria-pressed'),'true');await p.locator('.review-step-tabs button').nth(2).click();await p.locator('textarea[name=next]').fill('USER_INPUT_LONG 原文保留'.repeat(40));assert.equal(await p.locator('.action-review').evaluate(e=>e.scrollWidth>e.clientWidth),false);if(lang==='en'){await p.locator('textarea[name=next]').fill('USER INPUT');assert.equal((await p.locator('.action-review').innerText()).match(/[\u4e00-\u9fff]+/g),null);}await shot(width+'-写作-'+lang,null,width===390&&lang==='zh');}await load('PT05',390,'zh','/plan?tab=复盘&task=missing');assert.equal(await p.locator('.review-journal').count(),0);assert.match(await p.locator('.action-review').innerText(),/请重新选择/);});
assert.deepEqual(errors,[]);
}finally{await fs.writeFile(dir+'/浏览器验收.json',JSON.stringify({results,errors},null,2));await browser.close();}if(errors.length||results.some(r=>r.status==='fail'))process.exitCode=1;
